def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    prev_active_bids = []
    david_like_bid = None
    rich_aggressive = 0
    low_pressure_count = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if prev.get('status') != 'dead':
                    prev_active_bids.append(float(bid))
                if 48 <= float(bid) <= 60:
                    if david_like_bid is None or float(bid) > david_like_bid:
                        david_like_bid = float(bid)
                if float(bid) >= 75 and opp.get('budget', 0) > 300:
                    rich_aggressive += 1
                if float(bid) <= 45:
                    low_pressure_count += 1

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_highest_prev = max(prev_active_bids) if prev_active_bids else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Urgency from health and deprivation
    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    # Supply pressure heuristic
    if supply <= 16:
        pressure = 'tight'
    elif supply >= 22:
        pressure = 'loose'
    else:
        pressure = 'mid'

    # Base strategy
    if urgent:
        if active_highest_prev >= 85:
            bid = 90.0
        elif david_like_bid is not None:
            bid = david_like_bid + 2.5
        else:
            bid = max(62.0, active_highest_prev + 2.0)
    elif semi_urgent:
        if pressure == 'tight':
            if david_like_bid is not None:
                bid = david_like_bid + 1.5
            else:
                bid = max(56.0, min(72.0, active_highest_prev + 1.5))
        elif pressure == 'mid':
            bid = max(42.0, min(60.0, avg_prev * 0.9 if avg_prev > 0 else 49.0))
        else:
            bid = 34.0
    else:
        if pressure == 'loose':
            bid = 18.0 if rich_aggressive >= 2 else 24.0
        elif pressure == 'mid':
            if active_highest_prev <= 56:
                bid = min(58.0, active_highest_prev + 1.2)
            else:
                bid = 31.0 if rich_aggressive >= 2 else 39.0
        else:
            if david_like_bid is not None and rich_aggressive == 0:
                bid = david_like_bid + 1.2
            elif rich_aggressive >= 2:
                bid = 28.0
            else:
                bid = 47.0

    # Endgame survival adjustment
    if day >= 8:
        if hp <= 5:
            bid = max(bid, 68.0)
        elif pressure == 'loose':
            bid = max(bid, 26.0)

    # Budget discipline
    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(soft_cap, max(22.0, budget / (reserve_days + 0.5) + 8.0))

    if urgent:
        soft_cap = budget

    bid = min(bid, soft_cap, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Fallback
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    supply = float(day_context['supply'])
    day = day_context['day']

    # Yesterday bids from previous_trace (immediate reaction only)
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate pressure level from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = DAILY_SALARY * 0.6
        second_prev_bid = highest_prev_bid

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))

    # Supply pressure: with low supply, competition is tighter; bid higher.
    # supply is between 15 and 25.
    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    # When supply is low, supply_factor ~0 => we bid higher.
    scarcity_multiplier = 1.25 - 0.25 * supply_factor

    # Decide bid target based on our hp and yesterday's aggression.
    # If our hp is low, we must secure water; if high, we can slightly undercut.
    if my_hp <= 2.0:
        target = max(DAILY_SALARY * 0.85, second_prev_bid * 0.95)
    elif my_hp <= 4.0:
        target = max(DAILY_SALARY * 0.65, second_prev_bid * 0.8)
    else:
        # Underbid slightly relative to highest aggressors to save budget while still contesting.
        target = min(highest_prev_bid * 0.95, max(DAILY_SALARY * 0.55, second_prev_bid * 0.75))

    target *= scarcity_multiplier

    # Convert to an absolute bid cap by budget.
    # Also avoid overspending: keep within a fraction of budget depending on hp.
    if my_hp <= 2.0:
        budget_fraction = 0.95
    elif my_hp <= 4.0:
        budget_fraction = 0.8
    else:
        budget_fraction = 0.65

    bid = float(min(my_budget * budget_fraction, target))

    # Ensure non-negative and at least a small amount if budget allows.
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and my_budget > 0.0:
        bid = float(min(my_budget, DAILY_SALARY * 0.2))

    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0
    base_bid = DAILY_SALARY * 0.35
    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.7
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.5
    if highest_prev_bid > DAILY_SALARY * 0.8:
        if my_status['hp'] > 3:
            base_bid = DAILY_SALARY * 0.3
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.6)
    elif highest_prev_bid > DAILY_SALARY * 0.5:
        base_bid = min(my_status['budget'], max(base_bid, highest_prev_bid + 1))
    bid = min(my_status['budget'], base_bid)
    return bid
